      Editor.prototype.getNearPosition = function() {
        let e = new THREE.Vector3(0, -5, -30);
        e.applyQuaternion(this.camera.getWorldQuaternion());
        let t = this.camera.getWorldPosition();
        t.add(e.multiplyScalar(1));
        return [Math.round(t.x), Math.round(t.y), Math.round(t.z)];
      };
      Editor.prototype.selectAsset = function(e, t) {
        closeWindow();
        if (t) {
          if (t == 3) {
            fetch("https://user-assets.krunker.io/" + e + "/data.json", {
              cache: "no-cache"
            }).then((e2) => e2.json()).catch(() => alert("Error loading Prefab")).then((e2) => {
              if (!e2) {
                return alert("Error loading Prefab");
              }
              if (e2.map) {
                return alert("Invalid Prefab");
              }
              if (e2.objects) {
                e2 = e2.objects;
              }
              var t2 = this.settings.createObjectNear ? this.getNearPosition() : [0, 0, 0];
              this.replaceObject(
                this.fakeSelected(...t2),
                JSON.stringify(e2),
                true,
                false,
                true
              );
            });
          } else if (t == 4) {
            if (this.transformControl.object) {
              this.transformControl.object.userData.owner.assetTexture = parseInt(e) || 0;
              this.updateObjConfigGUI();
            }
          } else {
            this.gameConfig.aID = e;
            GUI.panel.state.refresh("panel_left_essential");
          }
        } else {
          var n = this.settings.createObjectNear ? this.getNearPosition() : [0, 0, 0];
          this.addObject(
            new ObjectInstance(
              {
                i: 44,
                aid: e,
                p: n
              },
              true
            )
          );
        }
      };
      Editor.prototype.selectMod = function(e) {
        closeWindow();
        this.mapConfig.modURL = e;
        GUI.panel.state.refresh("panel_left_essential");
      };
