      Editor.prototype.generateLists = function() {
        this.materialList = {
          Default: 0,
          Phong: 1,
          Basic: 2,
          Lambert: 3
        };
        this.textureList = {
          Default: "DEFAULT"
        };
        for (var e = 0; e < ASSETS.textures.length; e++) {
          if ((tmpObj = ASSETS.textures[e]).name != "DEFAULT") {
            this.textureList[UTILS.formatConstName(tmpObj.name)] = tmpObj.name;
          }
        }
        this.blendingList = {};
        for (e = 0; e < config.particleBlending.length; e++) {
          this.blendingList[UTILS.formatConstName(config.particleBlending[e])] = e;
        }
        this.particleList = {};
        for (e = 0; e < config.particleIDS.length; e++) {
          this.particleList[UTILS.formatConstName(config.particleIDS[e])] = e;
        }
        this.soundsList = {};
        for (e = 0; e < config.emitterSounds.length; e++) {
          this.soundsList[config.emitterSounds[e]] = e;
        }
        this.EASE_LIST = Terrain.EASE_LIST;
        this.skinList = {};
        var t;
        for (e = 0; e < STORE.skins.length; e++) {
          if (!(t = STORE.skins[e]).type || t.type != 4 && t.type != 5) {
            this.skinList[t.name + " [" + this.getItemDesc(t) + "]"] = e;
          }
        }
      };
      Editor.prototype.getItemDesc = function(e) {
        if (e.type == 1) {
          return "Head";
        } else if (e.type == 2) {
          return "Back";
        } else if (e.type == 3) {
          return "Melee";
        } else if (e.type == 6) {
          return "Waist";
        } else if (e.type == 7) {
          return "Face";
        } else {
          return WEAPONS[e.weapon - 1].name;
        }
      };
