      Editor.prototype.updateTheme = function() {
        [...document.styleSheets].filter((e) => e.title == "dark").forEach((e) => e.disabled = !this.settings.darkMode);
      };
      Editor.prototype.initRenderer = function() {
        this.renderer = new THREE.WebGLRenderer({
          precision: "mediump",
          powerPreference: "high-performance",
          antialias: !!this.settings.antiAlias,
          alpha: true
        });
        this.renderer.setPixelRatio(window.devicePixelRatio * 0.6);
        this.renderer.setSize(
          this.container.offsetWidth,
          this.container.offsetHeight
        );
        this.renderer.autoClear = false;
        this.container.appendChild(this.renderer.domElement);
        this.raycaster = new THREE.Raycaster();
        this.mouse = new THREE.Vector2();
        this.setResMlt();
      };
      Editor.prototype.initScene = function() {
        this.scene = new THREE.Scene();
        this.backgroundScene = new THREE.Scene();
        this.backgroundScene.background = new THREE.Color(15790320);
        this.camera = new THREE.PerspectiveCamera(
          70,
          this.container.offsetWidth / this.container.offsetHeight,
          1,
          1e4
        );
        this.sun = new THREE.Mesh(
          new THREE.SphereGeometry(5, 6, 6),
          new THREE.MeshBasicMaterial({
            color: 16711680,
            wireframe: true,
            transparent: true
          })
        );
        this.sun.scale.set(4, 4, 4);
        this.scene.add(this.sun);
        initScene.apply(this, [this.mapConfig]);
        this.updateSun();
        this.updateGridHelper();
        this.updateDeathBarrier();
      };
      Editor.prototype.updateSun = function() {
        var e = Math.PI * (this.mapConfig.sunAngY / -180);
        var t = Math.PI * (this.mapConfig.sunAngX / -180);
        this.skyLight.position.x = this.mapConfig.lightD * Math.cos(t);
        this.skyLight.position.y = this.mapConfig.lightD * Math.sin(t) * Math.sin(e);
        this.skyLight.position.z = this.mapConfig.lightD * Math.sin(t) * Math.cos(e);
        this.sun.position.copy(this.skyLight.position);
        this.sun.material.color.set(this.skyLight.color);
      };
      var PARTICLES = null;
      Editor.prototype.regenTerrain = function() {
        this.scene.remove(this.terrain);
        this.terrain = null;
        if (this.mapConfig.terrainSeed) {
          this.terrain = Terrain.fromConfig(this.mapConfig);
          this.terrain.clutterMesh = new THREE.Mesh();
          this.terrain.add(this.terrain.clutterMesh);
          if (this.terrain.genObjs) {
            for (var e in this.terrain.objPos) {
              if (this.terrain.objPos.hasOwnProperty(e)) {
                for (var t = 0; t < this.terrain.objPos[e].length; t++) {
                  ObjectInstance.addTerrObj(
                    this.terrain.objPos[e][t],
                    e,
                    this.terrain,
                    PARTICLES
                  );
                }
              }
            }
            this.terrain.objPos = null;
          }
          this.terrain.rotation.x = -Math.PI / 2;
          this.terrain.clutterMesh.rotation.x = Math.PI / 2;
          this.scene.add(this.terrain);
        }
      };
      Editor.prototype.regenSky = function() {
        this.backgroundScene.remove(this.skyDome);
        this.skyDome = null;
        if (this.mapConfig.skyDome) {
          this.skyDome = SkyDome.fromConfig(RENDER, this.mapConfig);
          this.backgroundScene.add(this.skyDome);
        }
        regenSky.apply(this, [this.mapConfig]);
      };
      Editor.prototype.regenZone = function() {
        this.scene.remove(this.zone);
        this.zone = null;
        if (this.mapConfig.zone) {
          this.zone = Zone.fromConfig(this.mapConfig, true);
          this.scene.add(this.zone);
        }
      };
